func SetData(resource plugin.Resource, field string, val *llx.RawData) error {
	f, ok := setDataFields[resource.MqlName()+"."+field]
	if !ok {
		return errors.New("[rancher] cannot set '" + field + "' in resource '" + resource.MqlName() + "', field not found")
	}

	if ok := f(resource, val); !ok {
		return errors.New("[rancher] cannot set '" + field + "' in resource '" + resource.MqlName() + "', type does not match")
	}
	return nil
}

func SetAllData(resource plugin.Resource, args map[string]*llx.RawData) error {
	var err error
	for k, v := range args {
		if err = SetData(resource, k, v); err != nil {
			return err
		}
	}
	return nil
}

// mqlRancher for the rancher resource
type mqlRancher struct {
	MqlRuntime *plugin.Runtime
	__id       string
	// optional: if you define mqlRancherInternal it will be used here
	Version                                    plugin.TValue[string]
	ServerUrl                                  plugin.TValue[string]
	TelemetryOptIn                             plugin.TValue[string]
	ClusterTemplateEnforcement                 plugin.TValue[bool]
	AuthTokenMaxTtlMinutes                     plugin.TValue[int64]
	KubeconfigDefaultTokenTtlMinutes           plugin.TValue[int64]
	PasswordMinLength                          plugin.TValue[int64]
	LocalAuthEnabled                           plugin.TValue[bool]
	ExternalAuthEnabled                        plugin.TValue[bool]
	Settings                                   plugin.TValue[[]any]
	Clusters                                   plugin.TValue[[]any]
	Projects                                   plugin.TValue[[]any]
	GlobalRoles                                plugin.TValue[[]any]
	GlobalRoleBindings                         plugin.TValue[[]any]
	RoleTemplates                              plugin.TValue[[]any]
	ClusterRoleTemplateBindings                plugin.TValue[[]any]
	ProjectRoleTemplateBindings                plugin.TValue[[]any]
	ClusterTemplates                           plugin.TValue[[]any]
	PodSecurityAdmissionConfigurationTemplates plugin.TValue[[]any]
	AuthProviders                              plugin.TValue[[]any]
	Tokens                                     plugin.TValue[[]any]
	Users                                      plugin.TValue[[]any]
	RegistryCredentials                        plugin.TValue[[]any]
}

// createRancher creates a new instance of this resource
func createRancher(runtime *plugin.Runtime, args map[string]*llx.RawData) (plugin.Resource, error) {
	res := &mqlRancher{
		MqlRuntime: runtime,
	}

	err := SetAllData(res, args)
	if err != nil {
		return res, err
	}

	if res.__id == "" {
		res.__id, err = res.id()
		if err != nil {
			return nil, err
		}
	}

	if runtime.HasRecording {
		args, err = runtime.ResourceFromRecording("rancher", res.__id)
		if err != nil || args == nil {
			return res, err
		}
		return res, SetAllData(res, args)
	}

	return res, nil
}

